data.content:
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Arial', 'Microsoft YaHei', sans-serif;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    padding: 20px;
}

.container {
    background: white;
    border-radius: 10px;
    padding: 20px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
    max-width: 500px;
    width: 100%;
}

.header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
}

h1 {
    font-size: 48px;
    color: #776e65;
    font-weight: bold;
}

.score-container {
    display: flex;
    gap: 10px;
}

.score-box {
    background: #bbada0;
    padding: 10px 20px;
    border-radius: 5px;
    text-align: center;
    min-width: 80px;
}

.score-label {
    color: #eee4da;
    font-size: 12px;
    text-transform: uppercase;
    margin-bottom: 5px;
}

.score-value {
    color: white;
    font-size: 24px;
    font-weight: bold;
}

.game-intro {
    margin-bottom: 20px;
    text-align: center;
}

.game-intro p {
    color: #776e65;
    margin-bottom: 10px;
}

.new-game-btn {
    background: #8f7a66;
    color: white;
    border: none;
    padding: 10px 20px;
    border-radius: 5px;
    font-size: 16px;
    cursor: pointer;
    transition: background 0.3s;
}

.new-game-btn:hover {
    background: #9f8a76;
}

.game-board {
    background: #bbada0;
    border-radius: 10px;
    padding: 10px;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 10px;
    position: relative;
}

.cell {
    background: rgba(238, 228, 218, 0.35);
    border-radius: 5px;
    aspect-ratio: 1;
    display: flex;
    justify-content: center;
    align-items: center;
    font-size: 32px;
    font-weight: bold;
    color: #776e65;
    transition: all 0.15s ease-in-out;
}

.tile {
    background: #eee4da;
    border-radius: 5px;
    aspect-ratio: 1;
    display: flex;
    justify-content: center;
    align-items: center;
    font-size: 32px;
    font-weight: bold;
    color: #776e65;
    animation: appear 0.2s;
}

@keyframes appear {
    from {
        transform: scale(0);
        opacity: 0;
    }
    to {
        transform: scale(1);
        opacity: 1;
    }
}

.tile-2 { background: #eee4da; color: #776e65; }
.tile-4 { background: #ede0c8; color: #776e65; }
.tile-8 { background: #f2b179; color: #f9f6f2; }
.tile-16 { background: #f59563; color: #f9f6f2; }
.tile-32 { background: #f67c5f; color: #f9f6f2; }
.tile-64 { background: #f65e3b; color: #f9f6f2; }
.tile-128 { background: #edcf72; color: #f9f6f2; font-size: 28px; }
.tile-256 { background: #edcc61; color: #f9f6f2; font-size: 28px; }
.tile-512 { background: #edc850; color: #f9f6f2; font-size: 28px; }
.tile-1024 { background: #edc53f; color: #f9f6f2; font-size: 24px; }
.tile-2048 { background: #edc22e; color: #f9f6f2; font-size: 24px; }

.game-over {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 1000;
}

.game-over.hidden {
    display: none;
}

.game-over-content {
    background: white;
    padding: 40px;
    border-radius: 10px;
    text-align: center;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
}

.game-over-content h2 {
    color: #776e65;
    margin-bottom: 20px;
    font-size: 36px;
}

.game-over-content p {
    color: #776e65;
    margin-bottom: 20px;
    font-size: 20px;
}

.restart-btn {
    background: #8f7a66;
    color: white;
    border: none;
    padding: 15px 30px;
    border-radius: 5px;
    font-size: 18px;
    cursor: pointer;
    transition: background 0.3s;
}

.restart-btn:hover {
    background: #9f8a76;
}

@media (max-width: 600px) {
    h1 {
        font-size: 36px;
    }

    .tile {
        font-size: 24px;
    }

    .tile-128, .tile-256, .tile-512 {
        font-size: 20px;
    }

    .tile-1024, .tile-2048 {
        font-size: 18px;
    }
}

class Game2048 {
    constructor() {
        this.gridSize = 4;
        this.grid = [];
        this.score = 0;
        this.bestScore = parseInt(localStorage.getItem('bestScore')) || 0;
        this.gameWon = false;
        this.gameOver = false;

        this.gridContainer = document.getElementById('grid-container');
        this.tileContainer = document.getElementById('tile-container');
        this.scoreElement = document.getElementById('score');
        this.bestScoreElement = document.getElementById('best-score');
        this.gameMessage = document.getElementById('game-message');

        this.init();
    }

    init() {
        this.createGrid();
        this.setupEventListeners();
        this.newGame();
    }

    createGrid() {
        for (let i = 0; i < this.gridSize * this.gridSize; i++) {
            const cell = document.createElement('div');
            cell.className = 'grid-cell';
            this.gridContainer.appendChild(cell);
        }
    }

    setupEventListeners() {
        document.getElementById('new-game').addEventListener('click', () => this.newGame());
        document.getElementById('retry-btn').addEventListener('click', () => this.newGame());

        document.addEventListener('keydown', (e) => {
            if (this.gameOver) return;

            const keyMap = {
                'ArrowUp': 'up',
                'ArrowDown': 'down',
                'ArrowLeft': 'left',
                'ArrowRight': 'right'
            };

            if (keyMap[e.key]) {
                e.preventDefault();
                this.move(keyMap[e.key]);
            }
        });

        // 触摸支持
        let touchStartX = 0;
        let touchStartY = 0;

        this.tileContainer.addEventListener('touchstart', (e) => {
            touchStartX = e.touches[0].clientX;
            touchStartY = e.touches[0].clientY;
        });

        this.tileContainer.addEventListener('touchend', (e) => {
            if (this.gameOver) return;

            const touchEndX = e.changedTouches[0].clientX;
            const touchEndY = e.changedTouches[0].clientY;

            const dx = touchEndX - touchStartX;
            const dy = touchEndY - touchStartY;

            if (Math.abs(dx) > Math.abs(dy)) {
                this.move(dx > 0 ? 'right' : 'left');
            } else {
                this.move(dy > 0 ? 'down' : 'up');
            }
        });
    }

    newGame() {
        this.grid = Array(this.gridSize).fill(null).map(() => Array(this.gridSize).fill(0));
        this.score = 0;
        this.gameWon = false;
        this.gameOver = false;
        this.updateScore();
        this.hideMessage();
        this.tileContainer.innerHTML = '';

        this.addRandomTile();
        this.addRandomTile();
        this.render();
    }

    addRandomTile() {
        const emptyCells = [];
        for (let i = 0; i < this.gridSize; i++) {
            for (let j = 0; j < this.gridSize; j++) {
                if (this.grid[i][j] === 0) {
                    emptyCells.push({row: i, col: j});
                }
            }
        }

        if (emptyCells.length > 0) {
            const {row, col} = emptyCells[Math.floor(Math.random() * emptyCells.length)];
            this.grid[row][col] = Math.random() < 0.9 ? 2 : 4;
        }
    }

    move(direction) {
        let moved = false;
        const oldGrid = JSON.parse(JSON.stringify(this.grid));

        if (direction === 'left') {
            moved = this.moveLeft();
        } else if (direction === 'right') {
            moved = this.moveRight();
        } else if (direction === 'up') {
            moved = this.moveUp();
        } else if (direction === 'down') {
            moved = this.moveDown();
        }

        if (moved) {
            this.addRandomTile();
            this.render();
            this.updateScore();

            if (this.checkWin() && !this.gameWon) {
                this.gameWon = true;
                this.showMessage('你赢了！');
            } else if (this.checkGameOver()) {
                this.gameOver = true;
                this.showMessage('游戏结束！');
            }
        }
    }

    moveLeft() {
        let moved = false;
        for (let i = 0; i < this.gridSize; i++) {
            const row = this.grid[i].filter(val => val !== 0);
            const merged = [];

            for (let j = 0; j < row.length; j++) {
                if (j < row.length - 1 && row[j] === row[j + 1]) {
                    merged.push(row[j] * 2);
                    this.score += row[j] * 2;
                    j++;
                } else {
                    merged.push(row[j]);
                }
            }

            while (merged.length < this.gridSize) {
                merged.push(0);
            }

            if (JSON.stringify(this.grid[i]) !== JSON.stringify(merged)) {
                moved = true;
            }
            this.grid[i] = merged;
        }
        return moved;
    }

    moveRight() {
        this.reverseGrid();
        const moved = this.moveLeft();
        this.reverseGrid();
        return moved;
    }

    moveUp() {
        this.transposeGrid();
        const moved = this.moveLeft();
        this.transposeGrid();
        return moved;
    }

    moveDown() {
        this.transposeGrid();
        this.reverseGrid();
        const moved = this.moveLeft();
        this.reverseGrid();
        this.transposeGrid();
        return moved;
    }

    reverseGrid() {
        for (let i = 0; i < this.gridSize; i++) {
            this.grid[i].reverse();
        }
    }

    transposeGrid() {
        const newGrid = Array(this.gridSize).fill(null).map(() => Array(this.gridSize).fill(0));
        for (let i = 0; i < this.gridSize; i++) {
            for (let j = 0; j < this.gridSize; j++) {
                newGrid[j][i] = this.grid[i][j];
            }
        }
        this.grid = newGrid;
    }

    checkWin() {
        for (let i = 0; i < this.gridSize; i++) {
            for (let j = 0; j < this.gridSize; j++) {
                if (this.grid[i][j] === 2048) {
                    return true;
                }
            }
        }
        return false;
    }

    checkGameOver() {
        // 检查是否有空格
        for (let i = 0; i < this.gridSize; i++) {
            for (let j = 0; j < this.gridSize; j++) {
                if (this.grid[i][j] === 0) {
                    return false;
                }
            }
        }

        // 检查是否有相邻的相同数字
        for (let i = 0; i < this.gridSize; i++) {
            for (let j = 0; j < this.gridSize; j++) {
                const current = this.grid[i][j];
                if (j < this.gridSize - 1 && current === this.grid[i][j + 1]) {
                    return false;
                }
                if (i < this.gridSize - 1 && current === this.grid[i + 1][j]) {
                    return false;
                }
            }
        }

        return true;
    }

    render() {
        this.tileContainer.innerHTML = '';
        const cellSize = (this.tileContainer.offsetWidth - 45) / 4;

        for (let i = 0; i < this.gridSize; i++) {
            for (let j = 0; j < this.gridSize; j++) {
                const value = this.grid[i][j];
                if (value !== 0) {
                    const tile = document.createElement('div');
                    tile.className = `tile tile-${value > 2048 ? 'super' : value}`;
                    tile.textContent = value;
                    tile.style.width = `${cellSize}px`;
                    tile.style.height = `${cellSize}px`;
                    tile.style.left = `${j * (cellSize + 15)}px`;
                    tile.style.top = `${i * (cellSize + 15)}px`;
                    this.tileContainer.appendChild(tile);
                }
            }
        }
    }

    updateScore() {
        this.scoreElement.textContent = this.score;
        if (this.score > this.bestScore) {
            this.bestScore = this.score;
            localStorage.setItem('bestScore', this.bestScore);
        }
        this.bestScoreElement.textContent = this.bestScore;
    }

    showMessage(text) {
        this.gameMessage.querySelector('p').textContent = text;
        this.gameMessage.classList.add('show');
    }

    hideMessage() {
        this.gameMessage.classList.remove('show');
    }
}

// 初始化游戏
window.addEventListener('DOMContentLoaded', () => {
    new Game2048();
});
